using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
using ZFrame.View;

namespace ZFrame.View.Input.Tests
{
    /// <summary>
    /// EditMode tests of the 操作 tab (TASK-A-M3-03): the
    /// <see cref="SettingType.Binding"/> / <see cref="SettingType.BindingReset"/>
    /// rows generated by <see cref="SettingsRowFactory"/>, their waiting state,
    /// the conflict/cancel feedback and the map-wide reset — all against a FAKE
    /// <see cref="IBindingSettings"/>, so no Input System device or play mode is
    /// involved. Also pins the data side: the registry's 操作 page is now the
    /// real binding list and <see cref="SettingsModel"/> still refuses to give
    /// value-less rows a persisted value.
    /// </summary>
    public sealed class SettingsBindingRowTests
    {
        private GameObject _host;
        private string _root;

        [SetUp]
        public void SetUp()
        {
            _root = Path.Combine(Path.GetTempPath(), "zframe_binding_ui_tests_" + Guid.NewGuid().ToString("N"));
        }

        [TearDown]
        public void TearDown()
        {
            if (_host != null)
            {
                UnityEngine.Object.DestroyImmediate(_host);
                _host = null;
            }

            if (Directory.Exists(_root))
            {
                Directory.Delete(_root, recursive: true);
            }
        }

        private RectTransform Host()
        {
            if (_host == null)
            {
                _host = new GameObject("BindingRowTestHost", typeof(RectTransform));
            }

            return _host.GetComponent<RectTransform>();
        }

        private static SettingDefinition InteractDefinition()
        {
            return SettingDefinition.Binding("controls.bind.Interact", "交互", "Player/Interact");
        }

        private static Text Caption(GameObject row, string buttonName)
        {
            Transform label = row.transform.Find(buttonName + "/" + SettingsRowFactory.ButtonLabelName);
            Assert.IsNotNull(label, $"row must contain {buttonName}/{SettingsRowFactory.ButtonLabelName}");
            return label.GetComponent<Text>();
        }

        // ---------- row shape ----------

        [Test]
        public void BindingRow_RendersLabel_KeyButton_AndResetButton()
        {
            var bindings = new FakeBindings { Display = "E" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings);

            Assert.AreEqual("交互", row.transform.Find("Label").GetComponent<Text>().text);
            Assert.AreEqual("E", Caption(row, SettingsRowFactory.KeyButtonName).text, "键位按钮显示当前键位");
            Assert.AreEqual("恢复默认", Caption(row, "ResetButton").text);

            Button keyButton = row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>();
            Assert.IsTrue(keyButton.interactable);
            Assert.IsNull(row.GetComponentInChildren<Toggle>(), "binding rows are not toggles");
            Assert.IsNull(row.GetComponentInChildren<Slider>());
        }

        [Test]
        public void BindingRow_WithoutBackend_RendersDisabledControls()
        {
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, null);

            Button keyButton = row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>();
            Assert.IsFalse(keyButton.interactable, "无输入后端时键位按钮禁用（面板仍可打开）");
            Assert.AreEqual(SettingsRowFactory.NoBindingServiceText, Caption(row, SettingsRowFactory.KeyButtonName).text);
        }

        [Test]
        public void BindingRow_UnavailableBackend_IsDisabled()
        {
            var bindings = new FakeBindings { IsAvailable = false };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings);

            Assert.IsFalse(row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>().interactable);
        }

        // ---------- waiting state → outcomes ----------

        [Test]
        public void ClickingTheKeyButton_EntersWaitingState_ThenShowsTheNewKey()
        {
            var feedback = new List<string>();
            var bindings = new FakeBindings { Display = "E" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings, feedback.Add);

            Button keyButton = row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>();
            keyButton.onClick.Invoke();

            Assert.AreEqual(SettingsRowFactory.WaitingForInputText, Caption(row, SettingsRowFactory.KeyButtonName).text,
                "点击后进入等待态：按钮显示「按任意键…」");
            Assert.IsFalse(keyButton.interactable, "等待态禁止再次点击（避免叠加重绑定）");
            Assert.AreEqual("Player/Interact", bindings.LastRebindAction, "行必须把动作键交给重绑定服务");

            bindings.Display = "F";
            bindings.Complete(RebindOutcome.Done, Snapshot("Player/Interact", "Interact", 0, "<Keyboard>/f"));

            Assert.AreEqual("F", Caption(row, SettingsRowFactory.KeyButtonName).text, "完成后显示新键位");
            Assert.IsTrue(keyButton.interactable, "完成后按钮恢复可点");
            Assert.AreEqual(1, feedback.Count);
            StringAssert.Contains("已绑定", feedback[0]);
        }

        [Test]
        public void Conflict_KeepsTheOldKey_AndReportsIt()
        {
            var feedback = new List<string>();
            var bindings = new FakeBindings { Display = "E" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings, feedback.Add);

            row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>().onClick.Invoke();
            bindings.Complete(RebindOutcome.Conflict, Snapshot("Player/Pause", "Pause", 0, "<Keyboard>/e"));

            Assert.AreEqual("E", Caption(row, SettingsRowFactory.KeyButtonName).text, "冲突已回滚 → 显示旧键位");
            Assert.AreEqual(1, feedback.Count);
            StringAssert.Contains("冲突", feedback[0]);
            StringAssert.Contains("Pause", feedback[0], "反馈必须点名冲突的动作");
        }

        [Test]
        public void Cancelled_RestoresTheKey_AndReportsIt()
        {
            var feedback = new List<string>();
            var bindings = new FakeBindings { Display = "E" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings, feedback.Add);

            row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>().onClick.Invoke();
            bindings.Complete(RebindOutcome.Cancelled, null);

            Assert.AreEqual("E", Caption(row, SettingsRowFactory.KeyButtonName).text);
            StringAssert.Contains("取消", feedback[0]);
        }

        [Test]
        public void Failed_ReportsUnavailable_AndRestoresTheKey()
        {
            var feedback = new List<string>();
            var bindings = new FakeBindings { Display = "E" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings, feedback.Add);

            row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>().onClick.Invoke();
            bindings.Complete(RebindOutcome.Failed, null);

            Assert.AreEqual("E", Caption(row, SettingsRowFactory.KeyButtonName).text);
            Assert.IsTrue(row.transform.Find(SettingsRowFactory.KeyButtonName).GetComponent<Button>().interactable);
            StringAssert.Contains("不可用", feedback[0]);
        }

        [Test]
        public void PerRowReset_CallsResetBinding_AndRefreshesTheCaption()
        {
            var feedback = new List<string>();
            var bindings = new FakeBindings { Display = "F" };
            GameObject row = SettingsRowFactory.CreateRow(InteractDefinition(), Host(), null, bindings, feedback.Add);

            bindings.Display = "E"; // what ResetBinding will restore
            row.transform.Find("ResetButton").GetComponent<Button>().onClick.Invoke();

            Assert.AreEqual("Player/Interact", bindings.LastResetAction);
            Assert.AreEqual("E", Caption(row, SettingsRowFactory.KeyButtonName).text);
            Assert.AreEqual(1, feedback.Count);
        }

        // ---------- 全部恢复默认 ----------

        [Test]
        public void BindingResetRow_CallsResetAll_AndRaisesChange()
        {
            var feedback = new List<string>();
            var changed = new List<SettingDefinition>();
            var bindings = new FakeBindings();
            SettingDefinition definition = SettingDefinition.BindingReset("controls.resetAll", "全部恢复默认");

            GameObject row = SettingsRowFactory.CreateRow(
                definition, Host(), (d, v) => changed.Add(d), bindings, feedback.Add);

            Button button = row.GetComponentInChildren<Button>();
            Assert.AreEqual("全部恢复默认", Caption(row, "Button").text);
            Assert.IsNull(row.transform.Find("Label"), "reset-all row is one wide button (no label column)");

            button.onClick.Invoke();

            Assert.AreEqual(1, bindings.ResetAllCalls);
            CollectionAssert.AreEqual(new[] { definition }, changed, "视图/主持层需要知道重置发生（刷新键位文案）");
            Assert.AreEqual(1, feedback.Count);
            StringAssert.Contains("全部", feedback[0]);
        }

        // ---------- status line ----------

        [Test]
        public void StatusLine_IsAGeneratedEmptyTextRow()
        {
            GameObject status = SettingsRowFactory.CreateStatusLine(Host());
            Text text = status.GetComponent<Text>();

            Assert.IsNotNull(text);
            Assert.AreEqual(string.Empty, text.text);
            Assert.IsNotNull(status.GetComponent<LayoutElement>(), "feedback line is a layout-group child, never hand-placed");
        }

        // ---------- data side ----------

        [Test]
        public void ControlsPage_IsTheRealBindingList_WithAMapWideReset()
        {
            SettingsRegistry registry = SettingsRegistry.BuildDefaults();
            Assert.IsTrue(registry.TryGetPage("controls", out SettingsPage controls));

            CollectionAssert.AreEqual(
                new[]
                {
                    SettingType.Binding,
                    SettingType.Binding,
                    SettingType.Binding,
                    SettingType.Binding,
                    SettingType.Binding,
                    SettingType.Binding,
                    SettingType.Note,
                    SettingType.BindingReset,
                },
                controls.Settings.Select(s => s.Type).ToArray());

            CollectionAssert.AreEqual(
                new[]
                {
                    "Player/Move", "Player/Move", "Player/Move", "Player/Move",
                    "Player/Interact", "Player/Pause",
                },
                controls.Settings.Take(6).Select(s => s.ActionKey).ToArray(),
                "移动拆四向（同一复合轴）+ 交互/暂停各一行");

            Assert.AreEqual("手柄摇杆使用默认设置，暂不支持重绑定", controls.Settings[6].DisplayName,
                "手柄摇杆不提供重绑入口，只如实说明");
            Assert.AreEqual("全部恢复默认", controls.Settings[7].DisplayName);
        }

        [Test]
        public void BindingDefinition_RequiresAnActionKey()
        {
            Assert.Throws<ArgumentException>(() => SettingDefinition.Binding("x", "X", null));
            Assert.Throws<ArgumentException>(() => SettingDefinition.Binding("x", "X", string.Empty));
        }

        [Test]
        public void SettingsModel_TreatsBindingRowsAsValueLess()
        {
            var registry = new SettingsRegistry(new[]
            {
                new SettingsPage("controls", "操作", new[]
                {
                    SettingDefinition.Binding("controls.bind.Interact", "交互", "Player/Interact"),
                    SettingDefinition.BindingReset("controls.resetAll", "全部恢复默认"),
                    SettingDefinition.Toggle("controls.probe", "探针", true),
                }),
            });
            var model = new SettingsModel(registry, _root);

            Assert.Throws<InvalidOperationException>(() => model.Get<object>("controls.bind.Interact"));
            Assert.Throws<InvalidOperationException>(() => model.Set("controls.resetAll", 1));

            model.Save();
            string json = File.ReadAllText(model.FilePath);
            StringAssert.DoesNotContain("controls.bind.Interact", json, "键位不进 settings.json（由 input_bindings.json 负责）");
            StringAssert.Contains("controls.probe", json, "有值行照常持久化");
        }

        private static BindingSnapshot Snapshot(string actionKey, string actionName, int index, string path)
        {
            return new BindingSnapshot(actionKey, actionName, index, path, false, false);
        }

        /// <summary>Records the interactions the row performs; the test decides when/with what the rebind completes.</summary>
        private sealed class FakeBindings : IBindingSettings
        {
            private Action<RebindOutcome, BindingSnapshot> _pending;

            public bool IsAvailable { get; set; } = true;

            public string Display { get; set; } = "E";

            public string LastRebindAction { get; private set; }

            public string LastResetAction { get; private set; }

            public int ResetAllCalls { get; private set; }

            public string GetBindingDisplay(string actionKey)
            {
                return Display;
            }

            public string GetBindingDisplay(string actionKey, int bindingIndex)
            {
                return Display;
            }

            public void Rebind(string actionKey, Action<RebindOutcome, BindingSnapshot> onComplete)
            {
                Rebind(actionKey, -1, onComplete);
            }

            public void Rebind(string actionKey, int bindingIndex, Action<RebindOutcome, BindingSnapshot> onComplete)
            {
                LastRebindAction = actionKey;
                _pending = onComplete;
            }

            public void ResetBinding(string actionKey)
            {
                ResetBinding(actionKey, -1);
            }

            public void ResetBinding(string actionKey, int bindingIndex)
            {
                LastResetAction = actionKey;
            }

            public void ResetAll()
            {
                ResetAllCalls++;
                Display = "默认";
            }

            public void Complete(RebindOutcome outcome, BindingSnapshot snapshot)
            {
                Action<RebindOutcome, BindingSnapshot> pending = _pending;
                _pending = null;
                pending?.Invoke(outcome, snapshot);
            }
        }
    }
}
